/* Level 18 (Veldin (return)) code following mobyutil; generated by tools/overlay_src.py, stubs replaced by C as functions are matched. Starts at 0x00267000 (was mobyutil_00267000.c). */
#include "common.h"
#include "include_asm.h"

typedef struct {
    char pad0[0xA];
    unsigned char alpha;
} Level18Effect;

typedef struct {
    char pad0[0x10];
    float position[4];
} Level18Moby;

extern Level18Effect *GetFlaggedPvarWord(Level18Moby *);
extern float FastVecDist(void *, void *);
extern int truncate_float_to_s32(float);
extern char hero_globals_base[];

/* Set an attached effect's alpha from distance and the supplied scale. */
void set_moby_attached_effect_alpha_from_distance(Level18Moby *moby, float scale) {
    Level18Effect *effect;
    int alpha;

    if (moby == 0) {
        return;
    }
    effect = GetFlaggedPvarWord(moby);
    if (effect == 0) {
        return;
    }
    alpha = truncate_float_to_s32(FastVecDist(hero_globals_base + 0xE9D, moby->position) * 8.0f * scale) - 1;
    if (alpha >= 256) {
        alpha = 255;
    } else if (alpha < 0) {
        alpha = 0;
    }
    effect->alpha = alpha;
}
